mapper.update:
UPDATE fire_alert_log
SET notes = #{notes},
    admin_judgment = #{adminJudgment}
WHERE id = #{id}

mapper.select:
SELECT
id, label, confidence, video_url, image_path,
detected_at, location, admin_judgment, alert_status, alert_time, notes
FROM fire_alert_log
WHERE 1=1

    AND label = #{label}


    AND location = #{location}


    AND DATE_FORMAT(detected_at, '%Y-%m-%d') = #{date}

ORDER BY detected_at DESC
LIMIT #{limit} OFFSET #{page}

SELECT COUNT(*)
FROM fire_alert_log
WHERE 1=1

    AND label = #{label}


    AND location = #{location}


    AND DATE_FORMAT(detected_at, '%Y-%m-%d') = #{date}
